// Generated by Cypress Author on 2026-11-18

describe('Contact Form View & Submissions', () => {
  beforeEach(() => {
    cy.visit('/contact');
  });

  it('visit /contact → displays contact page header, aside cards, and contact form', () => {
    cy.contains('h1', 'Get in Touch').should('be.visible');
    cy.contains('p', 'Have a recipe question, culinary collaboration').should('be.visible');

    // Aside cards
    cy.contains('h2', 'Collaborations').should('be.visible');
    cy.contains('h2', 'Recipe Questions').should('be.visible');

    // Form inputs and initial button state
    cy.get('input[placeholder="Joe Smith"]').should('be.visible');
    cy.get('input[placeholder="yourname@example.com"]').should('be.visible');
    cy.get('input[placeholder="Recipe question / collaboration inquiry"]').should('be.visible');
    cy.get('textarea[placeholder="Your beautiful message..."]').should('be.visible');

    cy.get('button[type="submit"]')
      .should('be.visible')
      .and('be.disabled')
      .and('contain.text', 'Send Message');
  });

  it('enter invalid email format → displays validation error and keeps submit button disabled', () => {
    cy.get('input[placeholder="Joe Smith"]').type('Chef Delisha');
    cy.get('input[placeholder="yourname@example.com"]').type('not-a-valid-email');
    cy.get('input[placeholder="Recipe question / collaboration inquiry"]').type('Question');
    cy.get('textarea[placeholder="Your beautiful message..."]').type('Message body');

    cy.contains('mat-error', 'Email is invalid').should('be.visible');
    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('submit valid form with successful API response → shows success snackbar and resets inputs', () => {
    cy.intercept('POST', '**/api/contacts', {
      statusCode: 200,
      body: { success: true },
    }).as('submitContact');

    cy.get('input[placeholder="Joe Smith"]').type('Alex Johnson');
    cy.get('input[placeholder="yourname@example.com"]').type('alex@example.com');
    cy.get('input[placeholder="Recipe question / collaboration inquiry"]').type(
      'Collaboration Proposal',
    );
    cy.get('textarea[placeholder="Your beautiful message..."]').type(
      'Would love to collaborate on a new recipe series!',
    );

    cy.get('button[type="submit"]').should('not.be.disabled').click();

    cy.wait('@submitContact')
      .its('request.body')
      .should((body) => {
        expect(body.name).to.eq('Alex Johnson');
        expect(body.email).to.eq('alex@example.com');
        expect(body.subject).to.eq('Collaboration Proposal');
        expect(body.message).to.eq('Would love to collaborate on a new recipe series!');
      });

    // Snackbar notification appears
    cy.contains(
      'mat-snack-bar-container',
      'Message sent successfully! Delisha will get back to you soon.',
    ).should('be.visible');

    // Form fields reset
    cy.get('input[placeholder="Joe Smith"]').should('have.value', '');
    cy.get('input[placeholder="yourname@example.com"]').should('have.value', '');
  });

  it('submit form when API fails → displays error notification and leaves form intact', () => {
    cy.intercept('POST', '**/api/contacts', {
      statusCode: 500,
      body: { error: 'Internal Server Error' },
    }).as('submitContactFail');

    cy.get('input[placeholder="Joe Smith"]').type('Alex Johnson');
    cy.get('input[placeholder="yourname@example.com"]').type('alex@example.com');
    cy.get('input[placeholder="Recipe question / collaboration inquiry"]').type('Inquiry');
    cy.get('textarea[placeholder="Your beautiful message..."]').type('Test message');

    cy.get('button[type="submit"]').click();

    cy.wait('@submitContactFail');

    cy.contains(
      'mat-snack-bar-container',
      'Failed to send message. Please try again later.',
    ).should('be.visible');
  });
});
